1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.api.CartItem;
4	import com.loja.checkout.api.CheckoutRequest;
5	import com.loja.checkout.api.OrderSummary;
6	import com.loja.checkout.domain.*;
7	import org.springframework.stereotype.Service;
8	
9	import java.math.BigDecimal;
10	import java.math.RoundingMode;
11	import java.util.List;
12	
13	@Service
14	public class CheckoutService {
15	
16	    public OrderSummary calcularResumo(CheckoutRequest request) {
17	        // Validar dados de entrada
18	        String erroValidacao = validarPedido(request);
19	        if (erroValidacao != null) {
20	            return OrderSummary.erro(erroValidacao);
21	        }
22	
23	        try {
24	            List<CartItem> itens = request.getItens();
25	            NivelClube nivelClube = NivelClube.fromCodigo(request.getNivelClube());
26	            Regiao regiao = Regiao.fromCodigo(request.getRegiao());
27	            ModalidadeEntrega modalidade = ModalidadeEntrega.fromCodigo(request.getModalidadeEntrega());
28	            Cupom cupom = Cupom.fromCodigo(request.getCupom());
29	            FormaPagamento formaPagamento = FormaPagamento.fromCodigo(request.getFormaPagamento());
30	            int parcelas = request.getParcelas() != null ? request.getParcelas() : 1;
31	
32	            // 1. Calcula subtotal dos produtos
33	            BigDecimal subtotalProdutos = calcularSubtotalProdutos(itens);
34	
35	            // 2. Calcula desconto do cupom
36	            BigDecimal descontoCupom = calcularDescontoCupom(cupom, subtotalProdutos, itens);
37	
38	            // 3. Calcula frete
39	            BigDecimal frete = calcularFrete(modalidade, itens, nivelClube);
40	            int prazoEntregaDias = modalidade.getPrazoDias();
41	
42	            // 4. Calcula seguro
43	            BigDecimal seguro = calcularSeguro(subtotalProdutos, regiao);
44	
45	            // 5. Calcula total (antes do ajuste de pagamento)
46	            BigDecimal total = subtotalProdutos
47	                    .subtract(descontoCupom)
48	                    .add(frete)
49	                    .add(seguro);
50	
51	            // 6. Calcula ajuste de pagamento e valor final
52	            BigDecimal[] resultadoPagamento = calcularAjustePagamento(formaPagamento, total, parcelas);
53	            BigDecimal ajustePagamento = resultadoPagamento[0];
54	            BigDecimal totalFinal = resultadoPagamento[1];
55	            BigDecimal valorParcela = resultadoPagamento[2];
56	
57	            // 7. Calcula crédito para a próxima compra
58	            BigDecimal creditoProximaCompra = calcularCredito(nivelClube, subtotalProdutos);
59	
60	            // 8. Verifica se deve enviar brinde
61	            boolean brinde = nivelClube == NivelClube.OURO && subtotalProdutos.compareTo(new BigDecimal("500.00")) > 0;
62	
63	            // Monta resposta
